import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
   .version 8.0
   .target sm_89
   .address_size 64
   .extern .shared .align 4 .b8 smem[];
   .visible .entry convtrans3d_fwd(
       .param .u64 x_ptr,
       .param .u64 w_ptr,
       .param .u64 b_ptr,
       .param .u64 out_ptr,
       .param .u32 pB,
       .param .u32 pIC,
       .param .u32 pOC,
       .param .u32 pD,
       .param .u32 pH,
       .param .u32 pW,
       .param .u32 pOD,
       .param .u32 pOH,
       .param .u32 pOW,
       .param .u32 pkD,
       .param .u32 pkH,
       .param .u32 pkW,
       .param .u32 pStrideD,
       .param .u32 pStrideH,
       .param .u32 pStrideW,
       .param .u32 pPadD,
       .param .u32 pPadH,
       .param .u32 pPadW,
       .param .u32 pDilD,
       .param .u32 pDilH,
       .param .u32 pDilW,
       .param .u32 pOutPadD,
       .param .u32 pOutPadH,
       .param .u32 pOutPadW,
       .param .u32 pGroups
   )
   {
       .reg .pred  %p<20>;
       .reg .s32   %r<200>;
       .reg .s64   %rd<100>;
       .reg .f32   %f<8>;
       // Load pointers
       ld.param.u64 %rd1, [x_ptr];
       ld.param.u64 %rd2, [w_ptr];
       ld.param.u64 %rd3, [b_ptr];
       ld.param.u64 %rd4, [out_ptr];
       // Load scalar params
       ld.param.u32 %r30, [pB];
       ld.param.u32 %r31, [pIC];
       ld.param.u32 %r32, [pOC];
       ld.param.u32 %r33, [pD];
       ld.param.u32 %r34, [pH];
       ld.param.u32 %r35, [pW];
       ld.param.u32 %r36, [pOD];
       ld.param.u32 %r37, [pOH];
       ld.param.u32 %r38, [pOW];
       ld.param.u32 %r39, [pkD];
       ld.param.u32 %r40, [pkH];
       ld.param.u32 %r41, [pkW];
       ld.param.u32 %r42, [pStrideD];
       ld.param.u32 %r43, [pStrideH];
       ld.param.u32 %r44, [pStrideW];
       ld.param.u32 %r45, [pPadD];
       ld.param.u32 %r46, [pPadH];
       ld.param.u32 %r47, [pPadW];
       ld.param.u32 %r48, [pDilD];
       ld.param.u32 %r49, [pDilH];
       ld.param.u32 %r50, [pDilW];
       ld.param.u32 %r150, [pOutPadD];
       ld.param.u32 %r151, [pOutPadH];
       ld.param.u32 %r152, [pOutPadW];
       ld.param.u32 %r51, [pGroups];
       // Compute output x, y from grid
       mov.u32 %r1, %tid.x;
       mov.u32 %r2, %ntid.x;
       mov.u32 %r3, %ctaid.x;
       mad.lo.s32 %r4, %r3, %r2, %r1;        // ow index in %r4
       mov.u32 %r5, %tid.y;
       mov.u32 %r6, %ntid.y;
       mov.u32 %r7, %ctaid.y;
       mad.lo.s32 %r8, %r7, %r6, %r5;        // oh index in %r8
       mov.u32 %r9,  %tid.z;
       mov.u32 %r10, %ntid.z;
       mov.u32 %r11, %ctaid.z;
       // tilesD = (OD + blockDim.z - 1) / blockDim.z
       add.s32 %r52, %r36, %r10;
       add.s32 %r52, %r52, -1;
       div.s32 %r53, %r52, %r10;             // tilesD
       // d_tile = blockIdx.z % tilesD; t = blockIdx.z / tilesD
       rem.s32 %r54, %r11, %r53;             // d_tile
       div.s32 %r55, %r11, %r53;             // t
       // oc = t % OC; b = t / OC
       rem.s32 %r56, %r55, %r32;             // oc
       div.s32 %r57, %r55, %r32;             // b
       // od = d_tile * blockDim.z + threadIdx.z
       mad.lo.s32 %r58, %r54, %r10, %r9;     // od
       // oc_per_group and ic_per_group
       div.s32 %r59, %r32, %r51;    // ocpg
       div.s32 %r60, %r31, %r51;    // icpg
       // g = oc / ocpg; ocg = oc % ocpg
       div.s32 %r61, %r56, %r59;    // g
       rem.s32 %r64, %r56, %r59;    // ocg
       // ic_start = g * icpg; ic_end = ic_start + icpg
       mul.lo.s32 %r62, %r61, %r60;
       add.s32    %r63, %r62, %r60;
       // Compute linear thread id and threads per block
       // r110 = linear tid, r111 = threads per block
       mul.lo.s32 %r103, %r2, %r6;           // ntid.x * ntid.y
       mul.lo.s32 %r104, %r5, %r2;           // ty * ntid.x
       add.s32    %r110, %r1, %r104;         // tx + ty*ntid.x
       mad.lo.s32 %r110, %r9, %r103, %r110;  // + tz*(ntid.x*ntid.y)
       mul.lo.s32 %r111, %r2, %r6;
       mul.lo.s32 %r111, %r111, %r10;        // threads per block
       // total_elems to preload into shared memory: icpg * kD * kH * kW
       mul.lo.s32 %r112, %r60, %r39;
       mul.lo.s32 %r112, %r112, %r40;
       mul.lo.s32 %r113, %r112, %r41;        // total_elems
       // Shared memory base
        mov.u64 %rd60, smem;
       // Cooperative preload of weights for this (ocg) across all ic, kd, kh, kw
       mov.s32 %r114, %r110;                 // idx = linear tid
   PL_LOOP:
       setp.ge.s32 %p10, %r114, %r113;
       @%p10 bra PL_DONE;
       // Decompose sidx -> (ic_rel, kd, kh, kw)
       // kw = sidx % kW
       rem.s32 %r121, %r114, %r41;
       // tmp1 = sidx / kW
       div.s32 %r122, %r114, %r41;
       // kh = tmp1 % kH
       rem.s32 %r123, %r122, %r40;
       // tmp2 = tmp1 / kH
       div.s32 %r124, %r122, %r40;
       // kd = tmp2 % kD
       rem.s32 %r125, %r124, %r39;
       // ic_rel = tmp2 / kD
       div.s32 %r126, %r124, %r39;
       // t = (ic_start + ic_rel) * ocpg + ocg
       mul.lo.s32 %r127, %r126, %r59;
       add.s32    %r127, %r127, %r64;
       mul.lo.s32 %r128, %r62, %r59;   // ic_start * ocpg
       add.s32    %r127, %r127, %r128; // add group ic offset
       // weight global index = ((((t)*kD + kd)*kH + kh)*kW + kw)
       cvt.s64.s32 %rd70, %r127;
       cvt.s64.s32 %rd71, %r39;
       mul.lo.s64  %rd70, %rd70, %rd71;      // *kD
       cvt.s64.s32 %rd72, %r125;
       add.s64     %rd70, %rd70, %rd72;      // +kd
       cvt.s64.s32 %rd73, %r40;
       mul.lo.s64  %rd70, %rd70, %rd73;      // *kH
       cvt.s64.s32 %rd74, %r123;
       add.s64     %rd70, %rd70, %rd74;      // +kh
       cvt.s64.s32 %rd75, %r41;
       mul.lo.s64  %rd70, %rd70, %rd75;      // *kW
       cvt.s64.s32 %rd76, %r121;
       add.s64     %rd70, %rd70, %rd76;      // +kw
       shl.b64     %rd70, %rd70, 2;          // *4 bytes
       add.s64     %rd71, %rd2, %rd70;       // w address
       ld.global.f32 %f6, [%rd71];
       // Store to shared at sidx
       cvt.s64.s32 %rd80, %r114;
       shl.b64     %rd80, %rd80, 2;
       add.s64     %rd81, %rd60, %rd80;
       st.shared.f32 [%rd81], %f6;
       // next idx
       add.s32 %r114, %r114, %r111;
       bra PL_LOOP;
   PL_DONE:
       bar.sync 0;
       // Bounds check after cooperative preload: x<OW && y<OH && z<OD
       setp.lt.s32 %p0, %r4,  %r38;
       setp.lt.s32 %p1, %r8,  %r37;
       and.pred   %p0, %p0, %p1;
       setp.lt.s32 %p1, %r58, %r36;
       and.pred   %p0, %p0, %p1;
       @!%p0 bra END;
       // Accumulator
       mov.f32 %f0, 0f00000000;
       // Adjust od/oh/ow by output padding for transposed conv mapping
       sub.s32 %r146, %r58, %r150;
       sub.s32 %r147, %r8,  %r151;
       sub.s32 %r148, %r4,  %r152;
       // kd loop init
       mov.s32 %r70, 0;
   KD_LOOP:
       setp.ge.s32 %p2, %r70, %r39;
       @%p2 bra KD_DONE;
       // id0 = (od - outPadD) + padD - kd*dilD
       mul.lo.s32 %r71, %r70, %r48;     // kd * dilD
       sub.s32    %r72, %r45, %r71;     // padD - kd*dilD
       add.s32    %r72, %r146, %r72;    // id0
       // if (id0 % strideD != 0) continue
       rem.s32 %r73, %r72, %r42;
       setp.ne.s32 %p3, %r73, 0;
       @%p3 bra KD_CONT;
       // id = id0 / strideD
       div.s32 %r74, %r72, %r42;
       // if (id < 0 || id >= D) continue
       setp.lt.s32 %p4, %r74, 0;
       @%p4 bra KD_CONT;
       setp.ge.s32 %p4, %r74, %r33;
       @%p4 bra KD_CONT;
       // kh loop
       mov.s32 %r75, 0;
   KH_LOOP:
       setp.ge.s32 %p5, %r75, %r40;
       @%p5 bra KH_DONE;
       // ih0 = (oh - outPadH) + padH - kh*dilH
       mul.lo.s32 %r76, %r75, %r49;
       sub.s32    %r77, %r46, %r76;
       add.s32    %r77, %r147, %r77;
       // if (ih0 % strideH != 0) continue
       rem.s32 %r78, %r77, %r43;
       setp.ne.s32 %p6, %r78, 0;
       @%p6 bra KH_CONT;
       // ih = ih0 / strideH
       div.s32 %r79, %r77, %r43;
       // if (ih < 0 || ih >= H) continue
       setp.lt.s32 %p6, %r79, 0;
       @%p6 bra KH_CONT;
       setp.ge.s32 %p6, %r79, %r34;
       @%p6 bra KH_CONT;
       // kw loop
       mov.s32 %r80, 0;
   KW_LOOP:
       setp.ge.s32 %p7, %r80, %r41;
       @%p7 bra KW_DONE;
       // iw0 = (ow - outPadW) + padW - kw*dilW
       mul.lo.s32 %r81, %r80, %r50;
       sub.s32    %r82, %r47, %r81;
       add.s32    %r82, %r148, %r82;
       // if (iw0 % strideW != 0) continue
       rem.s32 %r83, %r82, %r44;
       setp.ne.s32 %p1, %r83, 0;
       @%p1 bra KW_CONT;
       // iw = iw0 / strideW
       div.s32 %r84, %r82, %r44;
       // if (iw < 0 || iw >= W) continue
       setp.lt.s32 %p1, %r84, 0;
       @%p1 bra KW_CONT;
       setp.ge.s32 %p1, %r84, %r35;
       @%p1 bra KW_CONT;
       // ic loop
       mov.s32 %r85, %r62;
   IC_LOOP:
       setp.ge.s32 %p2, %r85, %r63;
       @%p2 bra IC_DONE;
       // input linear index: (((b*IC + ic)*D + id)*H + ih)*W + iw
       mul.lo.s32 %r86, %r57, %r31;  // b*IC
       add.s32    %r86, %r86, %r85;  // + ic
       cvt.s64.s32 %rd10, %r86;      // (b*IC+ic)
       cvt.s64.s32 %rd11, %r33;      // D
       mul.lo.s64  %rd12, %rd10, %rd11; // *D
       cvt.s64.s32 %rd13, %r74;      // id
       add.s64     %rd12, %rd12, %rd13; // +id
       cvt.s64.s32 %rd14, %r34;      // H
       mul.lo.s64  %rd12, %rd12, %rd14; // *H
       cvt.s64.s32 %rd15, %r79;      // ih
       add.s64     %rd12, %rd12, %rd15; // +ih
       cvt.s64.s32 %rd16, %r35;      // W
       mul.lo.s64  %rd12, %rd12, %rd16; // *W
       cvt.s64.s32 %rd17, %r84;      // iw
       add.s64     %rd12, %rd12, %rd17; // +iw
       shl.b64     %rd12, %rd12, 2;     // *4 bytes
       add.s64     %rd20, %rd1, %rd12;  // x address
       ld.global.f32 %f1, [%rd20];
       // shared weight index for ic_rel, kd, kh, kw
       sub.s32    %r95, %r85, %r62;       // ic_rel
       mul.lo.s32 %r96, %r95, %r39;       // *kD
       add.s32    %r96, %r96, %r70;       // + kd
       mul.lo.s32 %r96, %r96, %r40;       // *kH
       add.s32    %r96, %r96, %r75;       // + kh
       mul.lo.s32 %r96, %r96, %r41;       // *kW
       add.s32    %r96, %r96, %r80;       // + kw
       cvt.s64.s32 %rd25, %r96;
       shl.b64     %rd25, %rd25, 2;       // *4 bytes
       add.s64     %rd26, %rd60, %rd25;   // smem addr
       ld.shared.f32 %f2, [%rd26];
       fma.rn.f32 %f0, %f1, %f2, %f0;
       add.s32 %r85, %r85, 1;
       bra IC_LOOP;
   IC_DONE:
   KW_CONT:
       add.s32 %r80, %r80, 1;
       bra KW_LOOP;
   KW_DONE:
   KH_CONT:
       add.s32 %r75, %r75, 1;
       bra KH_LOOP;
   KH_DONE:
   KD_CONT:
       add.s32 %r70, %r70, 1;
       bra KD_LOOP;
   KD_DONE:
       // Add bias if provided
       setp.ne.s64 %p1, %rd3, 0;
       @!%p1 bra NO_BIAS;
       {
           cvt.s64.s32 %rd30, %r56;   // oc
           shl.b64     %rd30, %rd30, 2;
           add.s64     %rd31, %rd3, %rd30;
           ld.global.f32 %f3, [%rd31];
           add.f32     %f0, %f0, %f3;
       }
   NO_BIAS:
       // Store to output: (((b*OC+oc)*OD+od)*OH+oh)*OW+ow
       mul.lo.s32 %r100, %r57, %r32;    // b*OC
       add.s32    %r100, %r100, %r56;   // + oc
       cvt.s64.s32 %rd40, %r100;
       cvt.s64.s32 %rd41, %r36;         // OD
       mul.lo.s64  %rd40, %rd40, %rd41; // *OD
       cvt.s64.s32 %rd42, %r58;         // od
       add.s64     %rd40, %rd40, %rd42; // +od
       cvt.s64.s32 %rd43, %r37;         // OH
       mul.lo.s64  %rd40, %rd40, %rd43; // *OH
       cvt.s64.s32 %rd44, %r8;          // oh
       add.s64     %rd40, %rd40, %rd44; // +oh
       cvt.s64.s32 %rd45, %r38;         // OW
       mul.lo.s64  %rd40, %rd40, %rd45; // *OW
       cvt.s64.s32 %rd46, %r4;          // ow
       add.s64     %rd40, %rd40, %rd46; // +ow
       shl.b64     %rd40, %rd40, 2;     // *4 bytes
       add.s64     %rd41, %rd4, %rd40;
       st.global.f32 [%rd41], %f0;
   END:
       ret;
   }
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_fwd")

class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and a square kernel using a custom PTX kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, 
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # Keep a ConvTranspose3d module solely for parameter storage/initialization and state_dict compatibility.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        w = self.conv_transpose3d.weight
        b = self.conv_transpose3d.bias
        assert w.is_cuda and w.dtype == torch.float32, "Weights must be CUDA float32"
        if b is not None:
            assert b.is_cuda and b.dtype == torch.float32, "Bias must be CUDA float32"

        B, IC, D, H, W = x.shape
        OC = self.conv_transpose3d.out_channels
        kD, kH, kW = w.shape[-3], w.shape[-2], w.shape[-1]

        # Extract parameters (as triples)
        strideD, strideH, strideW = self.conv_transpose3d.stride
        padD, padH, padW = self.conv_transpose3d.padding
        outPadD, outPadH, outPadW = self.conv_transpose3d.output_padding
        dilD, dilH, dilW = self.conv_transpose3d.dilation
        groups = self.conv_transpose3d.groups

        # Compute output dimensions
        OD = (D - 1) * strideD - 2 * padD + dilD * (kD - 1) + outPadD + 1
        OH = (H - 1) * strideH - 2 * padH + dilH * (kH - 1) + outPadH + 1
        OW = (W - 1) * strideW - 2 * padW + dilW * (kW - 1) + outPadW + 1

        out = torch.empty((B, OC, OD, OH, OW), device=x.device, dtype=x.dtype)
        icpg = IC // groups
        shared_bytes = 4 * icpg * kD * kH * kW

        module = _get_ptx_module()

        # Launch configuration
        block_x, block_y, block_z = 8, 8, 4
        grid_x = (OW + block_x - 1) // block_x
        grid_y = (OH + block_y - 1) // block_y
        tilesD = (OD + block_z - 1) // block_z
        grid_z = B * OC * tilesD

        bias_arg = b if b is not None else u64(0)

        module.launch(
            "convtrans3d_fwd",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x.contiguous(),
                w.contiguous(),
                bias_arg,
                out,
                i32(B),
                i32(IC),
                i32(OC),
                i32(D),
                i32(H),
                i32(W),
                i32(OD),
                i32(OH),
                i32(OW),
                i32(kD),
                i32(kH),
                i32(kW),
                i32(strideD),
                i32(strideH),
                i32(strideW),
                i32(padD),
                i32(padH),
                i32(padW),
                i32(dilD),
                i32(dilH),
                i32(dilW),
                i32(outPadD),
                i32(outPadH),
                i32(outPadW),
                i32(groups),
            ],
            shared_memory=shared_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

