import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans3d_fwd(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 pB,
    .param .u32 pIC,
    .param .u32 pOC,
    .param .u32 pD,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pOD,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pkD,
    .param .u32 pkH,
    .param .u32 pkW,
    .param .u32 pStrideD,
    .param .u32 pStrideH,
    .param .u32 pStrideW,
    .param .u32 pPadD,
    .param .u32 pPadH,
    .param .u32 pPadW,
    .param .u32 pDilD,
    .param .u32 pDilH,
    .param .u32 pDilW,
    .param .u32 pGroups
)
{
    .reg .pred  %p<16>;
    .reg .s32   %r<140>;
    .reg .s64   %rd<64>;
    .reg .f32   %f<8>;

    // Load pointers
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [out_ptr];

    // Load scalar params
    ld.param.u32 %r30, [pB];
    ld.param.u32 %r31, [pIC];
    ld.param.u32 %r32, [pOC];
    ld.param.u32 %r33, [pD];
    ld.param.u32 %r34, [pH];
    ld.param.u32 %r35, [pW];
    ld.param.u32 %r36, [pOD];
    ld.param.u32 %r37, [pOH];
    ld.param.u32 %r38, [pOW];
    ld.param.u32 %r39, [pkD];
    ld.param.u32 %r40, [pkH];
    ld.param.u32 %r41, [pkW];
    ld.param.u32 %r42, [pStrideD];
    ld.param.u32 %r43, [pStrideH];
    ld.param.u32 %r44, [pStrideW];
    ld.param.u32 %r45, [pPadD];
    ld.param.u32 %r46, [pPadH];
    ld.param.u32 %r47, [pPadW];
    ld.param.u32 %r48, [pDilD];
    ld.param.u32 %r49, [pDilH];
    ld.param.u32 %r50, [pDilW];
    ld.param.u32 %r51, [pGroups];

    // Compute output x, y from grid
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ntid.x;
