_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_fwd")

class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and a square kernel using a custom PTX kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, 
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # Keep a ConvTranspose3d module solely for parameter storage/initialization and state_dict compatibility.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        w = self.conv_transpose3d.weight
        b = self.conv_transpose3d.bias
        assert w.is_cuda and w.dtype == torch.float32, "Weights must be CUDA float32"
        if b is not None:
            assert b.is_cuda and b.dtype == torch.float32, "Bias must be CUDA float32"

        B, IC, D, H, W = x.shape
        OC = self.conv_transpose3d.out_channels
        kD, kH, kW = w.shape[-3], w.shape[-2], w.shape[-1]

        # Extract parameters (as triples)
        strideD, strideH, strideW = self.conv_transpose3d.stride
        padD, padH, padW = self.conv_transpose3d.padding
        outPadD, outPadH, outPadW = self.conv_transpose3d.output_padding
        dilD, dilH, dilW = self.conv_transpose3d.dilation
        groups = self.conv_transpose3d.groups

        # Compute output dimensions
        OD = (D - 1) * strideD - 2 * padD + dilD * (kD - 1) + outPadD + 1
        OH = (H - 1) * strideH - 2 * padH + dilH * (kH - 1) + outPadH + 1
        OW = (W - 1) * strideW - 2 * padW + dilW * (kW - 1) + outPadW + 1

        out = torch.empty((B, OC, OD, OH, OW), device=x.device, dtype=x.dtype)
        icpg = IC // groups
        shared_bytes = 4 * icpg * kD * kH * kW

        module = _get_ptx_module()

        # Launch configuration
        block_x, block_y, block_z = 8, 8, 4
        grid_x = (OW + block_x - 1) // block_x
        grid_y = (OH + block_y - 1) // block_y
        tilesD = (OD + block_z - 1) // block_z
        grid_z = B * OC * tilesD

        bias_arg = b if b is not None else u64(0)

        module.launch(
            "convtrans3d_fwd",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x.contiguous(),
                w.contiguous(),
                bias_arg,
                out,
                i32(B),
                i32(IC),
                i32(OC),
                i32(D),
                i32(H),
                i32(W),
                i32(OD),
                i32(OH),
                i32(OW),
                i32(kD),
                i32(kH),
                i32(kW),
                i32(strideD),
                i32(strideH),
                i32(strideW),
                i32(padD),
                i32(padH),
                i32(padW),
                i32(dilD),
                i32(dilH),
                i32(dilW),
                i32(outPadD),
                i32(outPadH),
                i32(outPadW),
                i32(groups),
            ],
            shared_memory=shared_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
